  "py": "# ===== shutdown.py =====\n\"\"\"Use case 2 (Hard): deploying and crashing workers without losing work.\"\"\"\nimport asyncio\nimport os\nfrom datetime import timedelta\n\nfrom temporalio import activity, workflow\nfrom temporalio.common import RetryPolicy\n\nTASK_QUEUE = \"render\"\n\n\n@activity.defn\nasync def render(job: str, work_dir: str, seconds: float) -> str:\n    info = activity.info()\n    # one marker file per attempt, so the test can see which attempt ran where\n    open(os.path.join(work_dir, f\"{job}.attempt{info.attempt}.started\"), \"w\").write(str(os.getpid()))\n    try:\n        for _ in range(int(seconds / 0.2)):\n            await asyncio.sleep(0.2)\n            activity.heartbeat()  # lets the service notice a dead worker in seconds instead of minutes\n    except asyncio.CancelledError:\n        # worker shutdown (grace period over) or workflow cancel. Say which, then re-raise.\n        open(os.path.join(work_dir, f\"{job}.attempt{info.attempt}.cancelled\"), \"w\").write(\n            \"worker-shutdown\" if activity.is_worker_shutdown() else \"other\")\n        raise\n    return f\"{job}:attempt{info.attempt}\"\n\n\n@workflow.defn\nclass RenderWorkflow:\n    @workflow.run\n    async def run(self, job: str, work_dir: str, seconds: float) -> str:\n        return await workflow.execute_activity(\n            render, args=[job, work_dir, seconds],\n            start_to_close_timeout=timedelta(seconds=60),\n            heartbeat_timeout=timedelta(seconds=2),\n            retry_policy=RetryPolicy(initial_interval=timedelta(seconds=1)))\n\n# ===== crashing_worker.py =====\n\"\"\"Run a worker in its own OS process so a test can SIGKILL it. usage: crashing_worker.py <address> <namespace>\"\"\"\nimport asyncio\nimport sys\n\nfrom temporalio.client import Client\nfrom temporalio.worker import Worker\n\nimport shutdown\n\n\nasync def main() -> None:\n    client = await Client.connect(sys.argv[1], namespace=sys.argv[2])\n    async with Worker(client, task_queue=shutdown.TASK_QUEUE, workflows=[shutdown.RenderWorkflow], activities=[shutdown.render]):\n        print(\"ready\", flush=True)\n        await asyncio.Event().wait()\n\n\nasyncio.run(main())",
  "ts": "// ===== shutdown.ts =====\n/* Use case 2 (Hard): deploying and crashing workers without losing work. */\nimport { proxyActivities } from '@temporalio/workflow';\nimport type * as activities from './shutdown.activities';\n\nconst { render } = proxyActivities<typeof activities>({\n  startToCloseTimeout: '60 seconds',\n  heartbeatTimeout: '2 seconds',\n  retry: { initialInterval: '1 second' },\n});\n\nexport async function renderWorkflow(job: string, workDir: string, seconds: number): Promise<string> {\n  return render(job, workDir, seconds);\n}\n\n// ===== shutdown.activities.ts =====\nimport { Context, heartbeat } from '@temporalio/activity';\nimport { writeFileSync } from 'node:fs';\nimport { join } from 'node:path';\n\nexport async function render(job: string, workDir: string, seconds: number): Promise<string> {\n  const { attempt } = Context.current().info;\n  // one marker file per attempt, so the test can see which attempt ran where\n  writeFileSync(join(workDir, `${job}.attempt${attempt}.started`), String(process.pid));\n  try {\n    for (let i = 0; i < Math.floor(seconds / 0.2); i++) {\n      await Context.current().sleep(200);\n      heartbeat(); // lets the service notice a dead worker in seconds instead of minutes\n    }\n  } catch (e) {\n    // worker shutdown (grace period over) or workflow cancel. Record the reason, then re-throw.\n    const reason = Context.current().cancellationSignal.reason;\n    writeFileSync(join(workDir, `${job}.attempt${attempt}.cancelled`), String((reason as Error)?.message ?? reason));\n    throw e;\n  }\n  return `${job}:attempt${attempt}`;\n}\n\n// ===== crashing.worker.ts =====\n/* Run a worker in its own OS process so a test can SIGKILL it. usage: node crashing.worker.js <address> <namespace> */\nimport { NativeConnection, Worker } from '@temporalio/worker';\nimport * as activities from './shutdown.activities';\n\nasync function main() {\n  const connection = await NativeConnection.connect({ address: process.argv[2] });\n  const worker = await Worker.create({\n    connection, namespace: process.argv[3], taskQueue: 'render',\n    workflowsPath: require.resolve('./shutdown'), activities,\n  });\n  console.log('ready');\n  await worker.run();\n}\nmain().catch((e) => { console.error(e); process.exit(1); });"
